// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    // fuzz parameters: an address 'from', an array of recipients 'tos', a value v and decimals _decimals
    // We must deploy an observing/behaving callee that implements transferFrom(address,address,uint256)
    function testFuzz_property(address from, address payable maybeAddr, uint256 v, uint256 _decimals, address[] memory _tos) public {
        // admissible domain: require non-empty recipients (the function requires this)
        vm.assume(_tos.length > 0);
        // bound decimals so multiplication doesn't overflow absurdly (keep wide)
        _decimals = bound(_decimals, 0, 18);
        // value bound keep it reasonable
        v = bound(v, 0, type(uint128).max);

        // Deploy a RecordingCallee that implements transferFrom and records calls
        RecordingCallee callee = new RecordingCallee();

        // Ensure the recipients include at least one address that is the callee's contract address
        // to observe at least one successful decoded call; replace first entry with callee address
        _tos[0] = address(callee);

        // call c.transfer and observe whether it returns or reverts using try/catch
        bool ok;
        try c.transfer(from, address(callee), _tos, v, _decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: For the correct contract, every call to transfer should succeed (ok == true)
        // because RecordingCallee exposes transferFrom selector; the mutant that uses bytes4(0x0)
        // will cause the low-level call to a proper transferFrom-target to fail for some inputs,
        // producing ok == false. We assert that the reference contract always returns true.
        assertTrue(ok);

        // Additionally, verify that RecordingCallee observed exactly _tos.length calls and decoded arguments
        // This also relies on the correct selector being used by the real contract.
        // read recorded counter from the callee (observable surface of helper)
        require(callee.callCount() == _tos.length, "callee did not record expected number of calls");

        // check that each recorded to matches the _tos entries
        for (uint i = 0; i < _tos.length; i++) {
            (address recordedFrom, address recordedTo, uint256 recordedValue) = callee.calls(i);
            assertTrue(recordedFrom == from);
            assertTrue(recordedTo == _tos[i]);
            assertTrue(recordedValue == v * (10 ** _decimals));
        }
    }
}

// Recording helper that implements transferFrom(address,address,uint256)
contract RecordingCallee {
    struct Call { address from; address to; uint256 value; }
    Call[] public recorded;

    // Expose a function matching the selector used by the correct contract
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        recorded.push(Call({from: from, to: to, value: value}));
        return true;
    }

    // accessors for the test to observe recorded calls
    function callCount() external view returns (uint) { return recorded.length; }
    function calls(uint i) external view returns (address, address, uint256) {
        Call storage c = recorded[i];
        return (c.from, c.to, c.value);
    }
}
